"""Write sources.bzl from a SPIRV-Tools source tree.

SPIRV-Tools' BUILD.bazel builds each library from a glob of one or more
directories' *.cpp files (and its CMake lists the same files by hand). This
applies those globs to the tree and writes the results out as Starlark data
for BUILD.

Usage:
    sources.py SRCDIR > sources.bzl
"""

import os
import sys

# Each library's directories, as BUILD.bazel globs them, with the files it
# excludes. mimalloc.cpp is only built when SPIRV-Tools uses mimalloc.
LIBRARIES = {
    "SPIRV_TOOLS_SOURCES": (["source", "source/util", "source/val"], ["source/mimalloc.cpp"]),
    "OPT_SOURCES": (["source/opt"], []),
    "LINK_SOURCES": (["source/link"], []),
    "REDUCE_SOURCES": (["source/reduce"], []),
    "LINT_SOURCES": (["source/lint"], []),
    "DIFF_SOURCES": (["source/diff"], []),
    "TOOLS_UTIL_SOURCES": (["tools/util"], []),
}


def glob(root, directories, excludes):
    found = []
    for directory in directories:
        for name in os.listdir(os.path.join(root, directory)):
            path = directory + "/" + name
            if name.endswith(".cpp") and path not in excludes:
                found.append(path)
    return sorted(found)


def main():
    root = sys.argv[1]
    out = sys.stdout
    out.write("# SPDX-FileCopyrightText: © 2026 Austin Seipp\n")
    out.write("# SPDX-License-Identifier: Apache-2.0\n\n")
    out.write("# @generated by sources.py from SPIRV-Tools' source tree. Do not edit;\n")
    out.write("# see sources-up-to-date in BUILD.\n")
    for name, (directories, excludes) in LIBRARIES.items():
        files = glob(root, directories, excludes)
        out.write("\n{} = [\n".format(name))
        for f in files:
            out.write('    "{}",\n'.format(f))
        out.write("]\n")


if __name__ == "__main__":
    main()
